/* Entry point for the Blizzaga (Brizag) magic effect. */
// FUNCTION: FF7 0x0057b6c0
void __cdecl BattleFx_MagicEnterIce3(int targetMask, int actorIdx)
{
    BattleFx_MagicLoadResIce3();
    BattleFx_MagicBeginIce3(targetMask, actorIdx);
}

/* Initializes Blizzaga (Brizag) effect tasks and audio. */
// FUNCTION: FF7 0x0057b6da
void __cdecl BattleFx_MagicBeginIce3(int targetMask, int actorIdx)
{
    *(int *)&g_BattleFxDrawListBufferTaskSlotPtr = (int)BATTLE_NEW_TASK_SLOT(BattleFx_SelectDrawListBuffer);
    Battle_AllocateResourceSlot(BattleFx_MagicIce3SetupTask);
    g_BattleMagicIce3TargetMask = targetMask;
}

/* Sets up target centroid and spawns single or group tasks for Blizzaga. */
// FUNCTION: FF7 0x0057b712
void __cdecl BattleFx_MagicIce3SetupTask(void)
{
    int actorIdx;
    BattleFxMagicIce3Fragment *desc;
    int count, solo;
    BattleFxIce3Task *task;

    actorIdx = 0;
    for (count = 0; actorIdx < 0xA; actorIdx++) {
        if ((g_BattleMagicIce3TargetMask & 1 << actorIdx) != 0) {
            count++;
            if (count == 1) {
                solo = actorIdx;
            }
        }
    }
    task = (BattleFxIce3Task *)BATTLE_CURRENT_TASK_SLOT;
    task->ownerSlot = BATTLE_TASK_FREE;
    desc = (BattleFxMagicIce3Fragment *)Gfx_GetPsxScratchpadPtr(0);
    desc->dataBlock = (int)&g_BattleMagicIce3MeshDesc;
    desc->duration = 0xA;
    desc->distBias = 0xC;
    if (count == 1) {
        task = (BattleFxIce3Task *)BATTLE_NEW_TASK_SLOT(BattleFx_MagicIce3TargetTimelineTask);
        Battle_GetBoneWorldPos(solo, g_BattleActorRecords[solo].targetBone, &task->pos.x);
        task->radius = g_BattleActorRecords[solo].radius + 0x100;
        if (task->radius > 0x66C) {
            task->radius = 0x66C;
        }
        task->stageIndex = 0;
        task->isGroup = 0;
        BattleFx_MagicIce3InitSingleTargetShatterModel(desc);
        Battle_DispatchSfxOpcodeDirect(SOUND_SFX_PLAY_1, Battle_ComputePanForEntity(g_BattleMagicIce3TargetMask), 0x79);
    } else {
        task = (BattleFxIce3Task *)BATTLE_NEW_TASK_SLOT(BattleFx_MagicIce3GroupTimelineTask);
        Battle_GetActorMaskCentroid(g_BattleMagicIce3TargetMask, &task->pos.x);
        task->pos.y = 0xFB00;
        task->radius = 0x700;
        g_BattleMagicIce3Centroid = task->pos;
        BattleFx_MagicIce3InitGroupShatterModel((BattleFxMagicIce3Fragment *)desc);
        Battle_DispatchSfxOpcodeDirect(SOUND_SFX_PLAY_CH2, Battle_ComputePanForEntity(g_BattleMagicIce3TargetMask), 0xA3);
    }
}

/* Initializes single-target ice shatter model for Blizzaga. */
// FUNCTION: FF7 0x0057b8ec
void __cdecl BattleFx_MagicIce3InitSingleTargetShatterModel(BattleFxMagicIce3Fragment *fragment)
{
    int cursor, dataBase;

    dataBase = fragment->dataBlock + 4;
    cursor = dataBase + *(int *)fragment->dataBlock;
    fragment->fragmentIndex = 0;
    cursor += 8;
    cursor = BattleFx_MagicIce3InitSingleTargetFragmentMotion(fragment, dataBase, cursor);
}

/* Initializes fragment motion vectors for single-target ice shatter. */
// FUNCTION: FF7 0x0057b938
int __cdecl BattleFx_MagicIce3InitSingleTargetFragmentMotion(BattleFxMagicIce3Fragment *fragment, int blockBase, int entryBlock)
{
    BattleFxIce3MotionOffsets *cursor;
    int vertSumX;
    int yTally;
    int vertexZ;
    BattleFxIce3FragmentMotion *pMotionVec;
    int i, bufIndex, rnd, ratio, distBias, numFragments;

    numFragments = *(int *)entryBlock;
    bufIndex = fragment->fragmentIndex;
    distBias = fragment->distBias;
    cursor = (BattleFxIce3MotionOffsets *)(entryBlock + 4);
    ratio = 0x49DA40 / fragment->duration;
    for (i = 0; i < numFragments; i++) {
        pMotionVec = (BattleFxIce3FragmentMotion *)(blockBase + cursor->blockOffset0);
        vertSumX = pMotionVec->vertSumX;
        yTally = pMotionVec->yTally;
        vertexZ = pMotionVec->vertexZ;
        pMotionVec = (BattleFxIce3FragmentMotion *)(blockBase + cursor->blockOffset1);
        vertSumX += pMotionVec->vertSumX;
        yTally += pMotionVec->yTally;
        vertexZ += pMotionVec->vertexZ;
        pMotionVec = (BattleFxIce3FragmentMotion *)(blockBase + cursor->blockOffset2);
        vertSumX += pMotionVec->vertSumX;
        yTally += pMotionVec->yTally;
        vertexZ += pMotionVec->vertexZ;
        vertSumX = vertSumX / 3;
        yTally = yTally / 3;
        vertexZ = vertexZ / 3;
        g_BattleMagicIce3FragmentBuffer[bufIndex].positionX = vertSumX;
        g_BattleMagicIce3FragmentBuffer[bufIndex].positionY = yTally;
        g_BattleMagicIce3FragmentBuffer[bufIndex].positionZ = vertexZ;
        yTally += 0x898;
        yTally = yTally * yTally / ratio;
        g_BattleMagicIce3FragmentBuffer[bufIndex].yTally = yTally;
        g_BattleMagicIce3FragmentBuffer[bufIndex].fadeCounter = 0;
        g_BattleMagicIce3FragmentBuffer[bufIndex].rotationZ = 0;
        g_BattleMagicIce3FragmentBuffer[bufIndex].rotationY = 0;
        g_BattleMagicIce3FragmentBuffer[bufIndex].rotationX = 0;
        rnd = rand();
        if ((rnd & 0x800) != 0) {
            g_BattleMagicIce3FragmentBuffer[bufIndex].velocityX = (rnd & 7) * 0xC;
        } else {
            g_BattleMagicIce3FragmentBuffer[bufIndex].velocityX = -((rnd & 7) * 0xC);
        }
        g_BattleMagicIce3FragmentBuffer[bufIndex].velocityY = 0;
        if ((rnd & 0x204080) != 0) {
            g_BattleMagicIce3FragmentBuffer[bufIndex].velocityZ = (rnd >> 3 & 7) * 0xC;
        } else {
            g_BattleMagicIce3FragmentBuffer[bufIndex].velocityZ = -((rnd >> 3 & 7) * 0xC);
        }
        g_BattleMagicIce3FragmentBuffer[bufIndex].accelerationY = -((yTally + distBias) * ((rnd & 3) + 2));
        bufIndex++;
        cursor++;
    }
    fragment->fragmentIndex = bufIndex;
    return (int)cursor;
}

