/* Group timeline task controlling multi-target Blizzaga sequence. */
// FUNCTION: FF7 0x0057d89b
void __cdecl BattleFx_MagicIce3GroupTimelineTask(void)
{
    BattleMagicIce3GroupSlot *targetPtr;
    BattleFxIce3GroupRecord *ribbon;
    int keyIdx;
    BattleFxIce3GroupTimeline *task;

    if (g_BattleIsPaused != 0) {
        return;
    }
    task = (BattleFxIce3GroupTimeline *)BATTLE_CURRENT_TASK_SLOT;
    if (task->frameCount < 4) {
        for (keyIdx = 0; keyIdx < 0x12; keyIdx++) {
            if (task->frameCount == g_BattleMagicIce3KeyframeTable[keyIdx].spawnFrame) {
                ribbon = (BattleFxIce3GroupRecord *)BATTLE_NEW_TASK_SLOT(BattleFx_MagicIce3SpiralRibbonTask);
                ribbon->params[0] = g_BattleMagicIce3KeyframeTable[keyIdx].words[0];
                ribbon->params[1] = g_BattleMagicIce3KeyframeTable[keyIdx].words[1];
                ribbon->params[2] = g_BattleMagicIce3KeyframeTable[keyIdx].words[2];
                ribbon->params[3] = g_BattleMagicIce3KeyframeTable[keyIdx].words[3];
                ribbon->params[4] = g_BattleMagicIce3KeyframeTable[keyIdx].words[4];
                ribbon->params[5] = g_BattleMagicIce3KeyframeTable[keyIdx].words[5];
                ribbon->params[6] = g_BattleMagicIce3KeyframeTable[keyIdx].words[6];
            }
        }
    }
    if (task->frameCount == 0x14) {
        targetPtr = (BattleMagicIce3GroupSlot *)BATTLE_NEW_TASK_SLOT(BattleFx_MagicIce3TargetTimelineTask);
        targetPtr->pos = task->pos;
        targetPtr->ratio = task->radius;
        targetPtr->isGroupTarget = 1;
        targetPtr->thresholdIndex = 0;
        Battle_DispatchSfxOpcodeDirect(SOUND_SFX_PLAY_CH1, Battle_ComputePanForEntity(g_BattleMagicIce3TargetMask), 0x79);
    }
    if (task->frameCount < 0xA) {
        g_BattleFxTimelineState.channel2 = 0;
        g_BattleFxTimelineState.channel1 = g_BattleFxTimelineState.channel2;
        g_BattleFxTimelineState.red = g_BattleFxTimelineState.channel1;
        g_BattleFxTimelineState.startValue = task->frameCount * 0xCC;
    } else {
        g_BattleFxTimelineState.startValue = 0x800;
    }
    if (task->frameCount >= 0x32) {
        task->ownerSlot = BATTLE_TASK_FREE;
    }
    (task->frameCount)++;
}

